export const ARTICLES: Article[] = [{"id":"art_xb1_01","moduleId":"MODULE_XB_1","title":"论语十二章","subtitle":null,"author":"论语","dynasty":"先秦","genre":"散文","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"子曰：“君子食无求饱，居无求安，敏于事而慎于言，就有道而正焉，可谓好学也已。”\n子曰：“人而不仁，如礼何？人而不仁，如乐何？”\n子曰：“朝闻道，夕死可矣。”\n子曰：“君子喻于义，小人喻于利。”\n子曰：“见贤思齐焉，见不贤而内自省也。”\n子曰：“质胜文则野，文胜质则史。文质彬彬，然后君子。”\n曾子曰：“士不可以不弘毅，任重而道远。仁以为己任，不亦重乎？死而后已，不亦远乎？”\n子曰：“譬如为山，未成一篑，止，吾止也。譬如平地，虽覆一篑，进，吾往也。”\n子曰：“知者不惑，仁者不忧，勇者不惧。”\n颜渊问仁。子曰：“克己复礼为仁。一日克己复礼，天下归仁焉。为仁由己，而由人乎哉？”\n子贡问曰：“有一言而可以终身行之者乎？”子曰：“其‘恕’乎！己所不欲，勿施于人。”\n子曰：“小子何莫学夫《诗》？《诗》可以兴，可以观，可以群，可以怨。迩之事父，远之事君，多识于鸟兽草木之名。”","paragraphs":["君子食无求饱，居无求安，敏于事而慎于言。","士不可以不弘毅，任重而道远。仁以为己任，不亦重乎？死而后已，不亦远乎？","己所不欲，勿施于人。"],"translation":"孔子说：君子饮食不贪求饱足，居住不贪图安逸。","annotations":["文质彬彬：质朴与文采配合得当。","弘毅：抱负远大、意志坚强。"],"sortOrder":1,"totalSegments":12,"totalCards":12},{"id":"art_xb1_02","moduleId":"MODULE_XB_1","title":"大学之道","subtitle":null,"author":"礼记","dynasty":"先秦","genre":"散文","isGaoKao72":true,"recitationScope":"课标选段（古之欲明明德于天下者……壹是皆以修身为本）","fullContent":"古之欲明明德于天下者，先治其国；欲治其国者，先齐其家；欲齐其家者，先修其身；欲修其身者，先正其心；欲正其心者，先诚其意；欲诚其意者，先致其知；致知在格物。物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。自天子以至于庶人，壹是皆以修身为本。","paragraphs":["古之欲明明德于天下者，先治其国；欲治其国者，先齐其家；欲齐其家者，先修其身；欲修其身者，先正其心；欲正其心者，先诚其意；欲诚其意者，先致其知；致知在格物。","物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。自天子以至于庶人，壹是皆以修身为本。"],"translation":"古代想要把光明德行彰显于天下的人，先治理好自己的国家；要治国先齐家，要齐家先修身，要修身先正心，要正心先诚意，要诚意先致知，致知在于格物。从天子到平民，一切都要以修身为根本。","annotations":["明明德：彰显弘扬光明德行。","格物：推究事物的原理。"],"sortOrder":2,"totalSegments":6,"totalCards":6},{"id":"art_xb1_03","moduleId":"MODULE_XB_1","title":"人皆有不忍人之心","subtitle":null,"author":"孟子","dynasty":"先秦","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"孟子曰：“人皆有不忍人之心。先王有不忍人之心，斯有不忍人之政矣；以不忍人之心行不忍人之政，治天下可运之掌上。所以谓人皆有不忍人之心者：今人乍见孺子将入于井，皆有怵惕恻隐之心；非所以内交于孺子之父母也，非所以要誉于乡党朋友也，非恶其声而然也。由是观之，无恻隐之心，非人也；无羞恶之心，非人也；无辞让之心，非人也；无是非之心，非人也。恻隐之心，仁之端也；羞恶之心，义之端也；辞让之心，礼之端也；是非之心，智之端也。人之有是四端也，犹其有四体也。有是四端而自谓不能者，自贼者也；谓其君不能者，贼其君者也。凡有四端于我者，知皆扩而充之矣，若火之始然，泉之始达。苟能充之，足以保四海；苟不充之，不足以事父母。”","paragraphs":["人皆有不忍人之心。恻隐之心，仁之端也；羞恶之心，义之端也；辞让之心，礼之端也；是非之心，智之端也。"],"translation":"每个人都有同情怜悯他人的心。","annotations":["四端：仁、义、礼、智四种发端。"],"sortOrder":3,"totalSegments":4,"totalCards":4},{"id":"art_xb1_04","moduleId":"MODULE_XB_1","title":"老子四章","subtitle":null,"author":"老子","dynasty":"先秦","genre":"散文","isGaoKao72":true,"recitationScope":"课标推荐《老子》八章，本库收录四章","fullContent":"第十一章：三十辐共一毂，当其无，有车之用。埏埴以为器，当其无，有器之用。凿户牖以为室，当其无，有室之用。故有之以为利，无之以为用。\n第二十四章：企者不立，跨者不行，自见者不明，自是者不彰，自伐者无功，自矜者不长。其在道也，曰余食赘行，物或恶之，故有道者不处。\n第三十三章：知人者智，自知者明。胜人者有力，自胜者强。知足者富，强行者有志。不失其所者久，死而不亡者寿。\n第六十四章：其安易持，其未兆易谋；其脆易泮，其微易散。为之于未有，治之于未乱。合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。民之从事，常于几成而败之。慎终如始，则无败事。","paragraphs":["合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。","知人者智，自知者明。胜人者有力，自胜者强。"],"translation":"三十根车辐汇集到一个车毂上。","annotations":["自伐：自我夸耀。","千里之行始于足下：事情从点滴做起。"],"sortOrder":4,"totalSegments":8,"totalCards":8},{"id":"art_xb1_05","moduleId":"MODULE_XB_1","title":"五石之瓠","subtitle":null,"author":"庄子","dynasty":"先秦","genre":"散文","isGaoKao72":true,"recitationScope":"课标选段（惠子谓庄子曰……则夫子犹有蓬之心也夫）","fullContent":"惠子谓庄子曰：“魏王贻我大瓠之种，我树之成而实五石。以盛水浆，其坚不能自举也。剖之以为瓢，则瓠落无所容。非不呺然大也，吾为其无用而掊之。”庄子曰：“夫子固拙于用大矣。宋人有善为不龟手之药者，世世以洴澼絖为事。客闻之，请买其方百金。聚族而谋曰：‘我世世为洴澼絖，不过数金；今一朝而鬻技百金，请与之。’客得之，以说吴王。越有难，吴王使之将。冬，与越人水战，大败越人，裂地而封之。能不龟手一也，或以封，或不免于洴澼絖，则所用之异也。今子有五石之瓠，何不虑以为大樽而浮乎江湖，而忧其瓠落无所容？则夫子犹有蓬之心也夫！”","paragraphs":["夫子固拙于用大矣。何不虑以为大樽而浮乎江湖，而忧其瓠落无所容？"],"translation":"惠子对庄子说：魏王赠送我大葫芦的种子。","annotations":["不龟（jūn）手：手不生冻疮裂口。"],"sortOrder":5,"totalSegments":3,"totalCards":3},{"id":"art_xb1_06","moduleId":"MODULE_XB_1","title":"兼爱","subtitle":null,"author":"墨子","dynasty":"先秦","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"圣人以治天下为事者也，必知乱之所自起，焉能治之；不知乱之所自起，则不能治。譬之如医之攻人之疾者然，必知疾之所自起，焉能攻之；不知疾之所自起，则弗能攻。治乱者何独不然？必知乱之所自起，焉能治之；不知乱之所自起，则不能治。\n圣人以治天下为事者也，不可不察乱之所自起。当察乱之所自起，起不相爱。臣子之不孝君父，所谓乱也。子自爱，不爱父，故亏父而自利；弟自爱，不爱兄，故亏兄而自利；臣自爱，不爱君，故亏君而自利。此所谓乱也。虽父之不慈子，兄之不慈弟，君之不慈臣，此亦天下之所谓乱也。虽至天下之为盗贼者，亦然。盗爱其室，不爱异室，故窃异室以利其室；贼爱其身，不爱人身，故贼人身以利其身。此何也？皆起不相爱。\n若使天下兼相爱，爱人若爱其身，犹有不孝者乎？视父兄与君若其身，恶施不孝？犹有不慈者乎？视子弟与臣若其身，恶施不慈？故不孝不慈亡有。犹有盗贼乎？视人之室若其室，谁窃？视人之身若其身，谁贼？故盗贼亡有。若使天下兼相爱，国与国不相攻，家与家不相乱，盗贼无有，君臣父子皆能孝慈，若此则天下治。","paragraphs":["圣人以治天下为事者也，不可不察乱之所自起。当察乱之所自起，起不相爱。","若使天下兼相爱，国与国不相攻，家与家不相乱，若此则天下治。"],"translation":"治理天下必须知道混乱由何而起。","annotations":["兼爱：无差别的普遍之爱。"],"sortOrder":6,"totalSegments":4,"totalCards":4},{"id":"art_xb1_recite_01","moduleId":"MODULE_XB_1_RECITE","title":"无衣","subtitle":null,"author":"诗经","dynasty":"先秦","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！\n岂曰无衣？与子同泽。王于兴师，修我矛戟。与子偕作！\n岂曰无衣？与子同裳。王于兴师，修我甲兵。与子偕行！","paragraphs":["岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！","岂曰无衣？与子同泽。王于兴师，修我矛戟。与子偕作！","岂曰无衣？与子同裳。王于兴师，修我甲兵。与子偕行！"],"translation":"谁说没有战衣？我和你同穿战袍。","annotations":["同仇：共同对敌。","偕作：一同振奋行动。"],"sortOrder":1,"totalSegments":3,"totalCards":3},{"id":"art_xb1_recite_02","moduleId":"MODULE_XB_1_RECITE","title":"春江花月夜","subtitle":null,"author":"张若虚","dynasty":"唐代","genre":"乐府","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"春江潮水连海平，海上明月共潮生。滟滟随波千万里，何处春江无月明！江流宛转绕芳甸，月照花林皆似霰；空里流霜不觉飞，汀上白沙看不见。江天一色无纤尘，皎皎空中孤月轮。江畔何人初见月？江月何年初照人？人生代代无穷已，江月年年望相似。不知江月待何人，但见长江送流水。\n白云一片去悠悠，青枫浦上不胜愁。谁家今夜扁舟子？何处相思明月楼？可怜楼上月裴回，应照离人妆镜台。玉户帘中卷不去，捣衣砧上拂还来。此时相望不相闻，愿逐月华流照君。鸿雁长飞光不度，鱼龙潜跃水成文。昨夜闲潭梦落花，可怜春半不还家。江水流春去欲尽，江潭落月复西斜。斜月沉沉藏海雾，碣石潇湘无限路。不知乘月几人归，落月摇情满江树。","paragraphs":["春江潮水连海平，海上明月共潮生。滟滟随波千万里，何处春江无月明！","江畔何人初见月？江月何年初照人？人生代代无穷已，江月年年望相似。","此时相望不相闻，愿逐月华流照君。不知乘月几人归，落月摇情满江树。"],"translation":"春天的江潮水势浩荡与大海连成一片。","annotations":["孤月轮：高悬的明月。","落月摇情满江树：西落的月光将离情洒满江边树林。"],"sortOrder":2,"totalSegments":8,"totalCards":8},{"id":"art_xb1_recite_03","moduleId":"MODULE_XB_1_RECITE","title":"将进酒","subtitle":null,"author":"李白","dynasty":"唐代","genre":"乐府","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"君不见，黄河之水天上来，奔流到海不复回。君不见，高堂明镜悲白发，朝如青丝暮成雪。\n人生得意须尽欢，莫使金樽空对月。天生我材必有用，千金散尽还复来。烹羊宰牛且为乐，会须一饮三百杯。\n岑夫子，丹丘生，将进酒，杯莫停。与君歌一曲，请君为我倾耳听。钟鼓馔玉不足贵，但愿长醉不复醒。古来圣贤皆寂寞，惟有饮者留其名。陈王昔时宴平乐，斗酒十千恣欢谑。主人何为言少钱，径须沽取对君酌。五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。","paragraphs":["君不见，黄河之水天上来，奔流到海不复回。君不见，高堂明镜悲白发，朝如青丝暮成雪。","天生我材必有用，千金散尽还复来。烹羊宰牛且为乐，会须一饮三百杯。","钟鼓馔玉不足贵，但愿长醉不复醒。呼儿将出换美酒，与尔同销万古愁。"],"translation":"你难道没看见，黄河奔腾之水从天上涌来。","annotations":["天生我材必有用：极言自信与豪迈。","与尔同销万古愁：同你消解万古愁闷。"],"sortOrder":3,"totalSegments":6,"totalCards":6},{"id":"art_xb1_recite_04","moduleId":"MODULE_XB_1_RECITE","title":"江城子·乙卯正月二十日夜记梦","subtitle":"乙卯正月二十日夜记梦","author":"苏轼","dynasty":"宋代","genre":"词","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"十年生死两茫茫，不思量，自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。\n夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行。料得年年肠断处，明月夜，短松冈。","paragraphs":["十年生死两茫茫，不思量，自难忘。千里孤坟，无处话凄凉。","夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行。"],"translation":"两人一生一死相隔整整十年，不去刻意思念，却自然难以忘怀。","annotations":["尘满面鬓如霜：形容风霜憔悴。","短松冈：长着矮松的山冈，指亡妻墓地。"],"sortOrder":4,"totalSegments":4,"totalCards":4}];
